mapper.insert:
INSERT INTO label_annotation (
    job_id, asset_id, annotator_id, version, status, annotation_json, created_by, updated_by
) VALUES (
    #{jobId}, #{assetId}, #{annotatorId}, 1, #{annotationStatus}, #{annotationJson},
    #{userId}, #{userId}
)

mapper.update:
UPDATE label_annotation_object ao
JOIN label_annotation a ON a.id = ao.annotation_id
    AND a.deleted = 0
    AND a.job_id = #{jobId}
SET ao.deleted = 1, ao.updated_by = #{userId}, ao.update_time = NOW()
WHERE ao.deleted = 0
  AND (
      (
          JSON_VALID(ao.attr_json)
          AND JSON_UNQUOTE(JSON_EXTRACT(ao.attr_json, '$.assetId')) = CAST(#{assetId} AS CHAR)
      )
      OR (
          a.asset_id = #{assetId}
          AND (
              ao.attr_json IS NULL
              OR NOT JSON_VALID(ao.attr_json)
              OR JSON_EXTRACT(ao.attr_json, '$.assetId') IS NULL
          )
      )
  )

