SELECT oc.id, oc.job_id AS jobId, oc.asset_id AS assetId, oc.object_key AS objectKey, oc.node, oc.comment_type AS commentType, oc.content, oc.pos_x AS posX, oc.pos_y AS posY, oc.pos_z AS posZ, oc.status, oc.created_by AS createdBy, u.nick_name AS createdByName, oc.create_time AS createTime FROM label_object_comment oc LEFT JOIN sys_user u ON u.user_id = oc.created_by WHERE oc.deleted = 0 AND oc.job_id = #{jobId}
AND oc.asset_id = #{assetId}
ORDER BY oc.id

